using UnityEngine;
namespace LWS.TruckBaseJumping {
// One bounded pool, shared by every human camera. Crates use PhysX; only explosives add blast forces.
public sealed class BaseSkyField:MonoBehaviour {
 public BaseJumpMatch match;public BaseSkyBody[] bodies;public ParticleSystem[] blasts;public int Explosions{get;private set;}System.Random random;float age;int effects;readonly BaseSkyBody[] pending=new BaseSkyBody[32];int head,tail;readonly float[] protectedUntil=new float[4];
 public void ResetField(int seed){random=new System.Random(seed);age=0;head=tail=effects=Explosions=0;System.Array.Clear(protectedUntil,0,4);foreach(var item in bodies){item.queued=false;item.recycleAt=4+item.index*.21f;item.gameObject.SetActive(false);}foreach(var fx in blasts)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 bool Spawn(BaseSkyBody item){for(int attempt=0;attempt<24;attempt++){var p=new Vector3((float)random.NextDouble()*140-70,125+(float)random.NextDouble()*75,(float)random.NextDouble()*140-70);if(new Vector2(p.x,p.z+60).magnitude<30)continue;bool safe=true;foreach(var j in match.jumpers)if(j.Released&&!j.Landed&&(j.truck.body.position-p).sqrMagnitude<22*22)safe=false;if(!safe)continue;item.gameObject.SetActive(true);item.queued=false;item.body.isKinematic=false;var interpolation=item.body.interpolation;item.body.interpolation=RigidbodyInterpolation.None;item.body.position=p;item.body.rotation=Quaternion.Euler(random.Next(360),random.Next(360),random.Next(360));item.transform.SetPositionAndRotation(p,item.body.rotation);item.body.interpolation=interpolation;item.body.linearVelocity=item.kind==2?new Vector3(p.x>0?-13:13,-3,2):new Vector3(0,-2,0);item.body.angularVelocity=new Vector3(1.2f,.6f,1.4f);if(item.trail!=null)item.trail.Clear();item.BeginSmoke();return true;}return false;}
 public void Queue(BaseSkyBody item){if(item.queued||!item.gameObject.activeSelf||tail-head>=pending.Length)return;item.queued=true;pending[tail++%pending.Length]=item;}
 public void Step(float dt,Vector3 wind){age+=dt;int budget=2;while(head<tail&&budget-->0){var item=pending[head++%pending.Length];if(!item.gameObject.activeSelf)continue;var p=item.body.position;item.gameObject.SetActive(false);item.recycleAt=age+8;var fx=blasts[effects++%blasts.Length];fx.transform.position=p;fx.Play();Explosions++;match.feedback.Play(2,0,true);foreach(var j in match.jumpers){if(!j.Released||j.Landed||age<protectedUntil[j.slot])continue;var delta=j.truck.body.position-p;float distance=delta.magnitude;if(distance>13)continue;delta.y=Mathf.Max(1,delta.y+2);float force=Mathf.Lerp(8,1,distance/13);j.truck.body.AddForce(delta.normalized*force,ForceMode.VelocityChange);j.truck.body.AddTorque(new Vector3(force*.3f,.4f,force*.2f),ForceMode.VelocityChange);protectedUntil[j.slot]=age+1.1f;match.Pulse(j.slot,.3f,.14f);}foreach(var neighbor in bodies)if(neighbor.kind==1&&neighbor.gameObject.activeSelf&&!neighbor.queued&&(neighbor.body.position-p).sqrMagnitude<64)Queue(neighbor);}if(head==tail)head=tail=0;
 foreach(var item in bodies){if(!item.gameObject.activeSelf){if(age>=item.recycleAt&&Spawn(item))item.recycleAt=float.PositiveInfinity;continue;}var p=item.body.position;if(p.y<4||Mathf.Abs(p.x)>160||Mathf.Abs(p.z)>160){item.gameObject.SetActive(false);item.recycleAt=age+5+item.index%5;continue;}item.body.AddForce(wind*(item.kind==2?.05f:.13f),ForceMode.Acceleration);if(item.kind==2)item.DriftSmoke(wind);}
 }
 public void StopField(){if(bodies!=null)foreach(var item in bodies)item.gameObject.SetActive(false);if(blasts!=null)foreach(var fx in blasts)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
}
}
